const voiceGateway='http://127.0.0.1:4180';
const voice={token:null,config:null,error:'',status:'Not connected',run:null,segments:[],proposals:[],questions:[],draft:{},analyses:0,tested:false,analysisBusy:false,seenDelegations:new Set()};
const beforeVoiceBind=bind,beforeVoiceRender=render,beforeVoiceSource=showSource,beforeVoiceField=workflowField;
const voiceCore=['name','contact','email','phone','area','price','services','bio','delivery','insurance'];
// Typed input is also available: assistant audio stays live, but no microphone opens.
const voiceAudio=new Audio();voiceAudio.autoplay=true;
async function gateway(path,body){const response=await fetch(voiceGateway+'/api/voice/'+path,{method:body===undefined?'GET':'POST',headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(voice.token?{Authorization:'Bearer '+voice.token}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(25000)});const data=await response.json();if(!response.ok)throw Error(data.error||'The local voice request failed.');return data}
function voiceScreen(){return heading('Talk through the details. Keep the facts.','A conversational assistant for the rep, with profile changes held for review.')+`<div class="voice-pilot-banner"><div><b>Small-scale GPT Live pilot</b><span>2-minute sessions · 30-second idle cutoff · 10 starts/day · 3 profile analyses/session</span></div><span class="tag">API key stays on this computer</span></div><div class="voice-layout"><section class="card voice-conversation"><div class="card-head"><div><span class="eyebrow">CONVERSATIONAL ASSISTANT</span><h2 style="margin-top:12px">I Do! profile assistant</h2></div><span class="voice-connection ${voice.run?.ready?'connected':''}" id="voice-status">${esc(voice.status)}</span></div><div class="voice-console"><div class="voice-orb ${voice.run?.ready?'active':''}" aria-hidden="true">${voice.run?.test?'↔':'◉'}</div><div><h3>${voice.run?.ready?'Conversation connected':voice.tested?'Connection tested':'Ready when you are.'}</h3><p>${voice.run?.ready?'Speak to the assistant. Suggestions appear alongside the conversation.':'Connect the local gateway, then start a conversation or test the connection without a microphone.'}</p><span class="voice-clock" id="voice-clock">${voice.run?voiceTimeRemaining():'02:00 maximum'}</span></div></div>${voice.error?`<div class="warning" role="status">${esc(voice.error)}</div>`:''}<div class="voice-controls"><button class="secondary" id="voice-connect" ${voice.run?'disabled':''}>${voice.token?'Refresh gateway':'Connect local gateway'}</button><button class="primary" id="voice-start" ${!voice.token||voice.run?'disabled':''}>Start voice</button><button class="secondary" id="voice-typed" ${!voice.token||voice.run?'disabled':''}>Use typed input · no mic</button><button class="secondary" id="voice-test" ${!voice.token||voice.run?'disabled':''}>Test connection · no mic</button>${voice.run?`<button class="secondary" id="voice-mute" ${!voice.run.ready||voice.run.test||voice.run.typed?'disabled':''}>${voice.run.muted?'Unmute mic':'Mute mic'}</button><button class="primary" id="voice-stop">End session</button>`:''}</div><p class="voice-disclosure">You’ll hear AI-generated speech. Microphone access starts only after you choose Start voice. Audio travels to OpenAI; the API key stays in the local gateway. Muting does not stop billing. End the session when finished.</p><div class="voice-gateway-info">${voice.config?`Gateway connected · GPT Live 1 + GPT-6 Luna · ${voice.config.startsToday}/10 starts used today. Connection tests also use a start.`:'Gateway: 127.0.0.1:4180. Run the local start-voice-pilot launcher on this computer. Your browser may ask for local-network access. If it blocks the connection, open the local version at '+`<a href="http://127.0.0.1:4180/?v=voice#voice" target="_blank" rel="noopener">127.0.0.1:4180 ↗</a>`}</div><div class="voice-caption-head"><h3>Conversation</h3><button class="text-btn" id="voice-export-captions" ${!voice.segments.length?'disabled':''}>Export transcript ↓</button></div><div class="voice-captions" id="voice-captions" role="log" aria-live="polite">${voiceCaptions()}</div><label for="voice-note">Add a typed clarification while connected</label><div class="voice-note-row"><input id="voice-note" placeholder="e.g. The starting price is $4,500 per wedding." ${!voice.run?.ready?'disabled':''}><button class="secondary" id="voice-note-send" ${!voice.run?.ready||voice.analysisBusy?'disabled':''}>Send note</button></div><small class="voice-analysis-count" id="voice-analysis-count">${voice.analyses}/3 analyses used · ${voice.analysisBusy?'Preparing grounded suggestions…':'No automatic field changes.'}</small></section><section class="card voice-profile"><div class="card-head"><div><span class="eyebrow">WORKING PROFILE</span><h2 style="margin-top:12px">Review before applying.</h2></div><span class="tag">Draft</span></div><div class="voice-context-controls"><button class="secondary" id="voice-current" ${voice.run?'disabled':''}>Use current draft</button><button class="text-btn" id="voice-sample" ${voice.run?'disabled':''}>Load sample context</button></div><p class="voice-context-note">Only the visible draft and your conversation are used. Loading sample context is explicit; missing fields stay empty.</p><div class="voice-draft-fields">${voiceCore.map(k=>`<div><label>${esc(labels[k])}</label><span>${esc(voice.draft[k]||'Not provided')}</span></div>`).join('')}</div><div class="voice-proposal-heading"><h3>Suggested updates</h3><span>${voice.proposals.filter(p=>!p.applied&&!p.dismissed).length} pending</span></div><div id="voice-proposals">${voiceProposals()}</div>${voice.questions.length?`<div class="voice-questions"><h3>Questions to resolve</h3><ul>${voice.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></div>`:''}<div class="footer"><small>Applied changes update the current in-browser draft.</small><button class="secondary" id="voice-export-profile" ${!Object.keys(voice.draft).length?'disabled':''}>Export draft ↓</button></div></section></div>`}
function voiceCaptions(){return voice.segments.length?voice.segments.map(s=>`<div class="voice-caption ${s.speaker}"><b>${s.speaker==='rep'?'Rep':'Assistant'}</b><p>${esc(s.text)}</p></div>`).join(''):'<p class="voice-empty">Your conversation will appear here. No audio or transcript is recorded by this app until you start a session.</p>'}
function voiceProposals(){return voice.proposals.length?voice.proposals.filter(p=>!p.dismissed).map(p=>`<article class="voice-proposal ${p.applied?'applied':''}"><label>${esc(labels[p.field])}</label><div class="voice-before">${esc(p.before||'Not provided')}</div><strong>${esc(p.value)}</strong><blockquote>“${esc(p.evidence)}”</blockquote><small>Rep conversation · ${p.applied?'Applied to draft':'Awaiting review'}</small>${p.applied?'':`<div><button class="primary" data-voice-apply="${p.id}">Apply update</button><button class="text-btn" data-voice-dismiss="${p.id}">Dismiss</button></div>`}</article>`).join(''):'<p class="voice-empty">Ask the assistant to fill a field, check missing details, or correct a value. Grounded suggestions will appear here.</p>'}
function voiceTimeRemaining(){return Math.max(0,Math.ceil(((voice.run?.expiresAt||Date.now())-Date.now())/1000))+' seconds remaining'}
function refreshVoice(){if(state.page==='voice')render()}
function appendVoiceText(speaker,text,start=Date.now(),end=start){if(typeof text!=='string'||!text)return;let segment=voice.segments.findLast(s=>s.speaker===speaker&&start-s.end<1800&&start>=s.start);if(segment){segment.text+=text;segment.end=end}else voice.segments.push({speaker,text,start,end});voice.segments=voice.segments.slice(-100);if(voice.run)voice.run.lastActivity=Date.now();if(state.page==='voice'){const captions=$('#voice-captions');if(captions){captions.innerHTML=voiceCaptions();captions.scrollTop=captions.scrollHeight}const exportButton=$('#voice-export-captions');if(exportButton)exportButton.disabled=false}}
function sendLive(run,type,content,delegationId=null){if(voice.run!==run||!run.ready||run.dc?.readyState!=='open')return;run.dc.send(JSON.stringify({type,event_id:crypto.randomUUID(),...(content===undefined?{}:{content,delegation_id:delegationId})}))}
async function analyzeVoice(run,delegationId){if(voice.run!==run||!run.ready||voice.seenDelegations.has(delegationId)||voice.analysisBusy)return;const dialogueId=delegationId.startsWith('typed-')?null:delegationId;voice.seenDelegations.add(delegationId);voice.error='';if(voice.analyses>=3){sendLive(run,'session.commentary.append','The pilot has used its three profile analyses. Please review the pending suggestions or end this session.',dialogueId);return}const transcript=voice.segments.filter(s=>s.speaker==='rep').map(s=>s.text).join('\n').slice(-6500);if(!transcript.trim()){sendLive(run,'session.commentary.append','Please tell me the vendor details you want me to help organize.',dialogueId);return}voice.analysisBusy=true;refreshVoice();sendLive(run,'session.thinking.append','Checking the rep’s statements against the current draft.',dialogueId);try{const result=await gateway('assist',{sessionId:run.sessionId,delegationId,transcript,profile:voice.draft});if(voice.run!==run)return;voice.analyses=result.analysesUsed;voice.questions=result.follow_up;for(const update of result.updates){if(!labels[update.field]||!transcript.includes(update.evidence))continue;voice.proposals=voice.proposals.filter(p=>p.field!==update.field||p.applied);voice.proposals.push({...update,id:crypto.randomUUID(),before:voice.draft[update.field]||'',applied:false,dismissed:false})}sendLive(run,'session.commentary.append',(result.summary+' '+(result.updates.length?'The suggested changes are waiting for your Apply action. ':'')+(result.follow_up[0]||'')).slice(0,1200),dialogueId);if(result.rejected)voice.error='Some suggestions lacked an exact quote and were withheld.';}catch(error){voice.error=error.message;sendLive(run,'session.commentary.append','I could not finish that profile analysis. No fields were changed. Please review the on-screen message.',delegationId)}finally{voice.analysisBusy=false;refreshVoice()}}
async function connectVoiceGateway(){voice.error='';voice.status='Connecting gateway…';refreshVoice();try{voice.config=await gateway('status');if(!voice.config.ready)throw Error('The local gateway cannot find the configured API key.');const capability=await gateway('connect',{});voice.token=capability.token;voice.status='Gateway ready';}catch(error){voice.token=null;voice.status='Gateway offline';voice.error=error instanceof TypeError?'Cannot reach the local gateway. Start start-voice-pilot.cmd, allow local-network access if prompted, or use the local version at 127.0.0.1:4180.':error.message}refreshVoice()}
async function stopVoice(reason='Session ended'){const run=voice.run;if(!run)return;if(run.stopping)return;run.stopping=true;voice.status='Ending session…';refreshVoice();clearTimeout(run.timeout);clearInterval(run.tick);run.stream?.getTracks().forEach(t=>t.stop());if(run.dc?.readyState==='open'&&run.ready)run.dc.send(JSON.stringify({type:'session.close',event_id:crypto.randomUUID()}));let closed=false;try{if(run.sessionId){const result=await gateway('close',{sessionId:run.sessionId});closed=result.closed}}catch{voice.error='The local gateway could not confirm hangup. Keep it running so its two-minute cutoff can close the session.'}finally{run.dc?.close();run.pc?.close();run.silentContext?.close();voiceAudio.srcObject=null;if(voice.run===run)voice.run=null;voice.status=closed||run.finalized||!run.sessionId?reason:'Close not confirmed';if(run.finalized&&voice.error.startsWith('The local gateway could not confirm hangup'))voice.error='';gateway('status').then(config=>{voice.config=config;refreshVoice()}).catch(()=>{});voice.analysisBusy=false;refreshVoice()}}
async function startVoice(mode=false){const test=mode===true,typed=mode==='typed';if(voice.run||!voice.token)return;voice.error='';voice.status=test?'Testing connection…':'Connecting voice…';voice.analyses=0;voice.seenDelegations.clear();const run={test,typed,pc:null,dc:null,stream:null,ready:false,muted:false,lastActivity:Date.now(),expiresAt:Date.now()+120000};voice.run=run;refreshVoice();try{const pc=new RTCPeerConnection();run.pc=pc;pc.ontrack=event=>{if(voice.run!==run)return;voiceAudio.srcObject=new MediaStream([event.track]);voiceAudio.play().catch(()=>{voice.error='Your browser blocked audio playback. Choose Play assistant audio.';refreshVoice()})};if(test||typed){run.silentContext=new AudioContext();const destination=run.silentContext.createMediaStreamDestination(),oscillator=run.silentContext.createOscillator(),gain=run.silentContext.createGain();gain.gain.value=0;oscillator.connect(gain).connect(destination);oscillator.start();await run.silentContext.resume();run.stream=destination.stream;}else run.stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});if(voice.run!==run){run.stream.getTracks().forEach(t=>t.stop());return}for(const track of run.stream.getAudioTracks())pc.addTrack(track,run.stream);const dc=pc.createDataChannel('oai-events');run.dc=dc;
dc.onmessage=({data})=>{if(voice.run!==run)return;let event;try{event=JSON.parse(data)}catch{return}if(event.type==='session.started'){run.ready=true;voice.status=test?'GPT Live connected · no mic':typed?'Connected · typed input':'Connected · microphone on';clearTimeout(run.timeout);run.lastActivity=Date.now();if(test){voice.tested=true;setTimeout(()=>{if(voice.run===run)stopVoice('Connection test passed')},500)}else sendLive(run,'session.commentary.append','Greet the rep in English. Say you can help organize their vendor profile, and ask which detail they want to work on.');refreshVoice();}else if(event.type==='session.input_transcript.delta')appendVoiceText('rep',event.delta,event.start_ms,event.end_ms);else if(event.type==='session.output_transcript.delta')appendVoiceText('assistant',event.delta,event.start_ms,event.end_ms);else if(event.type==='session.delegation.created'&&event.delegation?.target==='client')analyzeVoice(run,event.delegation.id);else if(event.type==='session.closed'){run.finalized=true;voice.status='Session closed';stopVoice('Session ended')}else if(event.type==='error'){voice.error=event.error?.message?.slice(0,300)||'The voice session reported an error.';refreshVoice()}};
dc.onclose=()=>{if(voice.run===run&&!run.stopping)stopVoice('Connection closed')};pc.onconnectionstatechange=()=>{if(['failed','disconnected'].includes(pc.connectionState)&&voice.run===run&&!run.stopping)stopVoice('Connection lost')};await pc.setLocalDescription(await pc.createOffer());if(pc.iceGatheringState!=='complete')await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Voice network negotiation timed out.')),10000);pc.addEventListener('icegatheringstatechange',()=>{if(pc.iceGatheringState==='complete'){clearTimeout(timer);resolve()}},{once:false})});if(voice.run!==run||run.stopping)return;const result=await gateway('session',{sdp:pc.localDescription.sdp,profile:voice.draft});run.sessionId=result.session.id;run.expiresAt=result.expiresAt;if(run.stopping){await gateway('close',{sessionId:run.sessionId});return}await pc.setRemoteDescription({type:'answer',sdp:result.transport.sdp});run.timeout=setTimeout(()=>{if(voice.run===run&&!run.ready){voice.error='GPT Live did not finish connecting. The session will be closed.';stopVoice('Connection timed out')}},15000);run.tick=setInterval(()=>{if(voice.run!==run)return;if(Date.now()>=run.expiresAt)stopVoice('Two-minute pilot limit reached');else if(run.ready&&!run.test&&Date.now()-run.lastActivity>=30000)stopVoice('Ended after 30 seconds idle');const clock=$('#voice-clock');if(clock)clock.textContent=voiceTimeRemaining()},1000);
}catch(error){voice.error=error.name==='NotAllowedError'?'Microphone access was not granted. No conversation started.':error.message||'The voice connection failed.';await stopVoice('Could not connect')}}
showSource=function(key){const proof=state.data.voiceEvidence?.[key];if(!proof){beforeVoiceSource(key);return}$('#source-title').textContent=labels[key]+' · Rep conversation';$('#source-copy').innerHTML=`<div class="current-value"><small>CURRENT DRAFT VALUE</small><strong>${esc(state.data[key])}</strong></div><div class="citation-label">${proof.value===state.data[key]?'Applied from the rep’s conversation':'Edited after the voice update; this quote supported the earlier value'}</div><pre class="evidence-document">${esc(proof.evidence)}</pre><p>Original suggested value: ${esc(proof.value)}. This is a conversation source, not independent vendor verification.</p>`;$('#source').showModal()};
workflowField=function(key,auto){let html=beforeVoiceField(key,auto);if(auto&&state.data.voiceEvidence?.[key])html=html.replace(/>(Vendor website|Follow-up email|Interview notes|Rate card|Portfolio) ↗</,'>Rep conversation ↗<');return html};
render=function(){beforeVoiceRender();if(state.page==='voice')$('#crumb').textContent='Voice assistant'};
bind=function(){beforeVoiceBind();document.querySelectorAll('nav [data-page]').forEach(button=>{const previous=button.onclick;button.onclick=async()=>{if(voice.run)await stopVoice('Ended on navigation');previous()}});if(state.page!=='voice')return;$('#voice-connect').onclick=connectVoiceGateway;$('#voice-start').onclick=()=>startVoice(false);$('#voice-test').onclick=()=>startVoice(true);if(document.getElementById('voice-typed'))document.getElementById('voice-typed').onclick=()=>startVoice('typed');if($('#voice-stop'))$('#voice-stop').onclick=()=>stopVoice();if($('#voice-mute'))$('#voice-mute').onclick=()=>{const run=voice.run;if(!run?.ready)return;run.muted=!run.muted;run.stream?.getAudioTracks().forEach(track=>track.enabled=!run.muted);sendLive(run,run.muted?'session.input_audio.mute':'session.input_audio.unmute');voice.status=run.muted?'Connected · microphone muted':'Connected · microphone on';refreshVoice()};$('#voice-current').onclick=()=>{voice.draft=Object.fromEntries(allKeys.filter(k=>typeof state.data[k]==='string'&&state.data[k]).map(k=>[k,state.data[k]]));if(!Object.keys(voice.draft).length)voice.draft={...state.manual};voice.proposals=[];voice.questions=[];refreshVoice()};$('#voice-sample').onclick=()=>{voice.draft={...samples[state.type]};voice.proposals=[];voice.questions=[];refreshVoice()};document.querySelectorAll('[data-voice-apply]').forEach(button=>button.onclick=()=>{const p=voice.proposals.find(p=>p.id===button.dataset.voiceApply);if(!p||p.applied)return;if((voice.draft[p.field]||'')!==p.before){toast('This draft value changed after the suggestion. Review a new suggestion before applying.');return}voice.draft[p.field]=p.value;state.data[p.field]=p.value;state.data.voiceEvidence={...state.data.voiceEvidence,[p.field]:{value:p.value,evidence:p.evidence,source:'Rep conversation'}};p.applied=true;if(p.field==='price'){rateDraft=p.value;decisions.price=false}refreshVoice();toast(labels[p.field]+' updated in the draft.')});document.querySelectorAll('[data-voice-dismiss]').forEach(button=>button.onclick=()=>{const p=voice.proposals.find(p=>p.id===button.dataset.voiceDismiss);if(p)p.dismissed=true;refreshVoice()});$('#voice-note-send').onclick=()=>{const text=$('#voice-note').value.trim(),run=voice.run;if(!text||!run?.ready)return;appendVoiceText('rep',text);$('#voice-note').value='';analyzeVoice(run,'typed-'+crypto.randomUUID())};$('#voice-export-captions').onclick=()=>evalDownload({conversation:voice.segments},'bubs-rep-conversation.json');$('#voice-export-profile').onclick=()=>evalDownload({category:state.type,...voice.draft,voiceEvidence:state.data.voiceEvidence||{}},'bubs-voice-draft.json');if(voice.error.includes('Play assistant audio')){const b=document.createElement('button');b.className='secondary';b.textContent='Play assistant audio';b.onclick=()=>voiceAudio.play();$('.voice-controls').append(b)}};
window.addEventListener('pagehide',()=>{const run=voice.run;if(run){run.stream?.getTracks().forEach(t=>t.stop());if(run.sessionId)fetch(voiceGateway+'/api/voice/close',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+voice.token},body:JSON.stringify({sessionId:run.sessionId}),keepalive:true}).catch(()=>{})}});
if(location.hash==='#voice'){state.page='voice';transcriptOrigin=false;}render();





